import{_ as d,C as a,o as n,c,j as t,a as o,E as s,ag as l}from"./chunks/framework.HG0H2VLS.js";const v=JSON.parse('{"title":"RecordScreen","description":"","frontmatter":{},"headers":[],"relativePath":"cc-templates/record-screen.md","filePath":"cc-templates/record-screen.md"}'),h={name:"cc-templates/record-screen.md"},p={id:"recordscreen",tabindex:"-1"};function g(u,e,m,b,f,w){const i=a("Badge"),r=a("ComponentDemo");return n(),c("div",null,[e[3]||(e[3]=t("hr",null,null,-1)),e[4]||(e[4]=t("h2",{id:"title-recordscreen",tabindex:"-1"},[o("title: RecordScreen "),t("a",{class:"header-anchor",href:"#title-recordscreen","aria-label":'Permalink to "title: RecordScreen"'},"​")],-1)),t("h1",p,[e[0]||(e[0]=o("RecordScreen ",-1)),s(i,{type:"info",text:"Design System"}),e[1]||(e[1]=o()),e[2]||(e[2]=t("a",{class:"header-anchor",href:"#recordscreen","aria-label":'Permalink to "RecordScreen <Badge type="info" text="Design System" />"'},"​",-1))]),e[5]||(e[5]=t("blockquote",null,[t("p",null,"ArticleView / ArticleEdit / ArticleSteps generated by `_generate")],-1)),s(r,{src:"/demos/src/cc/templates/RecordScreen/RecordScreen.html"}),e[6]||(e[6]=l('<h2 id="composition" tabindex="-1">Composition <a class="header-anchor" href="#composition" aria-label="Permalink to &quot;Composition&quot;">​</a></h2><p>Shell = ControlScreen/ListingScreen app shell, ported as a bundle by <code>_generate.py</code> (sidebar menu, TopNavigation, HeaderGroup, ActionsMenu rail, theme + width scripts). Page body:</p><ul><li><strong>CC Header Type=Record</strong> (<code>.cc-header--record</code>) — Figma RecordHeader <code>3867:2138</code></li><li><strong>RecordTabs</strong> — Details / Article steps are links between screens; Steps adds Import / + Add</li><li>View / Edit: <strong>RecordSection</strong> × 6 (FieldRow view or edit types) + sidebar <strong>FactPanel</strong> × 7 (PerformanceSummary, ViewerList, FactList × 4, AdvisoryList)</li><li>Steps: <strong>StepsTable</strong> (Datatables) — Show details expands every row</li><li>Import step (designer, 2026-09-30): the Steps screen with the table replaced by one edit-mode <strong>RecordSection</strong> &quot;Import step&quot; — Article Step (lookup → Selector <code>single</code>, two columns Article · Article step) + Sort Order (lookup → Selector <code>sort</code> over this article&#39;s steps, the new step appended last and badged &quot;Importing&quot;; default position = steps + 1). The tabs stay — Details still leads back to the article — and the tab actions become <strong>Cancel / Save</strong> (both return to Article steps). Replaces the legacy &quot;add Article Step Lookup&quot; form + its two popups.</li><li>Add step (designer, 2026-09-30): <strong>+ Add</strong> opens &quot;Add a step&quot; — a Modal <code>--sm</code> of two <strong>ActionCards</strong> (Right Chevron + the new code-first description line), Content Step / Dynamic Form Step with the legacy descriptions. Each links to its screen: the Import frame (tabs stay, Cancel / Save) with four stacked RecordSections — the legacy tabs Main / Layout / Background / Publication, the first titled by the step type. Fields, order, required flags, defaults and options are affino.com&#39;s <code>StepByStepFormDef.cfm</code> + <code>LiveEditStepByStepForm.cfm</code> (2026-09-30), built by <code>record_step.py</code>: Content = 32 fields; Dynamic Form = Dynamic Form + the file&#39;s own shared list (12). Legacy&#39;s one-Dynamic-Form-Step-per-article rule: <code>?form=exists</code> disables that card and says why.</li><li>Edit: two FilterDropdowns <strong>Multi Select Modals</strong> (Multi Display, Topics and Keywords) for TagBox</li></ul><h2 id="shell-paint-table-step-3a-—-read-from-the-frames-2026-09-28" tabindex="-1">Shell paint table (Step 3a — read from the frames 2026-09-28) <a class="header-anchor" href="#shell-paint-table-step-3a-—-read-from-the-frames-2026-09-28" aria-label="Permalink to &quot;Shell paint table (Step 3a — read from the frames 2026-09-28)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Layout</th><th>Wrapper</th><th>Value</th></tr></thead><tbody><tr><td>Standard</td><td>page bg</td><td>shell <code>--cc-ui-primary-bg</code> (screen frame <code>#E7EDF0</code>; the body&#39;s own white fill is hidden)</td></tr><tr><td>Standard</td><td>page padding</td><td><strong>= the Listing screen&#39;s</strong> (designer, 2026-09-29, for consistency): <code>.cc-control__page</code> base — <code>--ai-spacing-6</code> desktop, <code>--ai-spacing-4</code> &lt;768, same scrollbar-gutter trims. Was <code>--ai-spacing-5</code>/5/6 on <code>.record-screen</code>. Figma content containers updated: <code>spacing/6</code> on the 7 desktop/narrow frames, <code>spacing/4</code> on the 2 mobile frames. Tabs → content gap <code>--ai-spacing-5</code> (<code>--ai-spacing-4</code> below 768, designer amend 2026-09-30)</td></tr><tr><td>Standard</td><td>columns</td><td>gap <code>--ai-spacing-5</code>; sidebar <code>max-width: --ai-size-7</code> (384)</td></tr><tr><td>Standard</td><td>main / sidebar</td><td>section gap <code>--ai-spacing-5</code> / panel gap <code>--ai-spacing-5</code></td></tr><tr><td>Full</td><td>page</td><td>flush (ccWidth), <code>--ai-surface-primary</code></td></tr><tr><td>Full</td><td>columns</td><td>gap 0; main column right border <code>--ai-border-secondary</code></td></tr><tr><td>Full</td><td>sidebar</td><td>padding <code>--ai-spacing-5</code>, gap <code>--ai-spacing-5</code>, max-width <code>--ai-size-7</code></td></tr></tbody></table><h2 id="interactions-designer-2026-09-28" tabindex="-1">Interactions (designer, 2026-09-28) <a class="header-anchor" href="#interactions-designer-2026-09-28" aria-label="Permalink to &quot;Interactions (designer, 2026-09-28)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Element</th><th>Behaviour</th><th>Owner</th></tr></thead><tbody><tr><td>Details / Article steps tabs</td><td>navigate between screens; menu open/closed and width persist</td><td>links + <code>RecordScreen.js</code></td></tr><tr><td>Sidebar edge (View / Edit)</td><td>drag to resize the sidebar (designer, 2026-09-28 — the Seating Planner model): invisible <code>role=&quot;separator&quot;</code> strip on the sidebar&#39;s leading edge, col-resize cursor; full width tints the main column&#39;s border <code>--ai-surface-contrast</code> on hover/drag. Min <code>--ai-size-7</code> (384, Figma&#39;s width — designer), max half the row, ←/→ 16px, Home/End, double-click resets. Width kept per viewer (<code>localStorage cc-record-sidebar-w</code>) across View ↔ Edit</td><td><code>RecordScreen.js</code></td></tr><tr><td>Actions-rail <strong>Minimise</strong> (<code>fold-vertical</code> / <code>unfold-vertical</code> when on, 2026-10-01)</td><td>visual only — the older framework&#39;s condensed spacing view (<code>data-layout=&quot;minimised&quot;</code>); kept beside Full width (2026-10-01)</td><td><code>TODO(backend:ControlScreen) [minimise]</code></td></tr><tr><td>Actions-rail <strong>Full width</strong> (<code>unfold-horizontal</code> / <code>fold-horizontal</code>, 2026-10-01)</td><td>toggles full width (designer, 2026-09-28): <code>aria-pressed</code>, rail active look, choice saved (<code>localStorage cc-width</code>) and followed on every record screen; <code>?template=</code> still wins when present</td><td><code>control-width.js</code> (<code>data-cc-width-toggle</code>, opt-in per screen)</td></tr><tr><td>Edit / Cancel</td><td>View ↔ Edit screens</td><td>links</td></tr><tr><td>SEO Health ± / Expand all</td><td>expand inline</td><td><code>AdvisoryItem.js</code></td></tr><tr><td>Image details (View)</td><td>file facts hidden by default; &quot;Image details&quot; opens them in a Dropdown panel (layout B, designer 2026-09-29)</td><td><code>Dropdown.js</code></td></tr><tr><td>TagBox × / Select</td><td>remove tag · Multi Select Modal (pre-ticked, Apply writes back)</td><td><code>TagBox.js</code></td></tr><tr><td>Show details</td><td>reveals the step body on every row (only)</td><td><code>StepsTable.js</code> + <code>Toggle.js</code></td></tr><tr><td>Step kebab</td><td>reveals only that row&#39;s columns that did not fit</td><td>Datatables / <code>ListingScreen.js</code></td></tr><tr><td><strong>Show sidebar</strong> switch (far right of the tabs, View / Edit)</td><td>hides / shows the sidebar; <strong>View on, Edit off</strong> by default (in the markup — no flash), then the viewer&#39;s own choice <strong>per mode</strong> (localStorage <code>cc-record-sidebar-view</code> / <code>-edit</code>; handover <code>record-sidebar-preference</code>); desktop only — at a ≤1023 page the switch goes and the sidebar stacks under the content (designer, 2026-09-29; code-first, flag for Figma)</td><td>Toggle.js + <code>RecordScreen.js</code> (<code>.record-screen--no-sidebar</code>)</td></tr><tr><td>Steps Edit Columns / Settings</td><td>the listing&#39;s own — the steps table runs on ListingScreen.js (<code>article-steps</code> config)</td><td><code>ListingScreen.js</code></td></tr><tr><td>Import (Steps tab actions)</td><td>opens the Import step screen</td><td>link</td></tr><tr><td>Header kebab (View, Steps and its Import / Add screens)</td><td>the CC header rule — one primary + one secondary, the rest in the kebab: Live view, Related items, Go to list (→ Articles listing), Copy. Edit mode has none (Cancel + Save only)</td><td><code>Dropdown.js</code>; <code>record_kebab()</code> in <code>record_markup.py</code>; HANDOVER <code>record-live-view</code> / <code>record-related-items</code> / <code>record-copy</code></td></tr><tr><td>+ Add (Steps tab actions)</td><td>opens the Add a step chooser; ×, Escape or backdrop closes, focus returns to + Add</td><td><code>RecordScreen.js</code> (<code>data-record-modal-open</code>)</td></tr><tr><td>Add step: Cancel / Save</td><td>return to Article steps; Save creates nothing (mock)</td><td>links + HANDOVER <code>steps-add-save</code></td></tr><tr><td>Colour rows</td><td>swatch + hex follow the native picker</td><td><code>RecordScreen.js</code></td></tr><tr><td>Import step: Cancel / Save</td><td>return to Article steps; Save adds nothing (mock)</td><td>links + HANDOVER <code>steps-import-save</code></td></tr><tr><td>Step checkboxes, pencil, Read the full step, + Add</td><td>visual only — backend later</td><td>HANDOVER</td></tr><tr><td>View full analytics, Add to Contact List, Save</td><td>backend</td><td>HANDOVER</td></tr></tbody></table><h2 id="verified-headless-chrome-2026-09-28" tabindex="-1">Verified (headless Chrome, 2026-09-28) <a class="header-anchor" href="#verified-headless-chrome-2026-09-28" aria-label="Permalink to &quot;Verified (headless Chrome, 2026-09-28)&quot;">​</a></h2><ul><li>All 16 pages&#39; 361 CSS/JS/image refs resolve (HTTP 200).</li><li>Probe: Show details reveals detail rows; select-all ticks 20; advisory ±, Expand all ↔ Collapse all; tag remove; modal opens pre-ticked (2) and Apply writes 4 tags back; <code>?template=full</code> sets <code>data-cc-width=&quot;full&quot;</code>, 6 <code>record-section--full</code>, flat tabs, and Edit keeps <code>?template=full</code>.</li><li>Measured: label column 192 / compact term 128; sidebar 384 in both widths.</li><li>Resize probe (both widths): drag −158px → 542; End → 384; Home → half the row; → −16; double-click → 384 + storage cleared; <code>elementFromPoint</code> on the edge hits the handle.</li><li><strong>Open:</strong> max (half the row) and the 16px step are carried from the Seating Planner, not a Figma value; standard width has no hover paint (cursor only) — no edge line exists between the two card columns to tint.</li><li>Light and dark (CC Dark) screenshots checked.</li></ul><h2 id="open-questions-known-gaps" tabindex="-1">Open questions / known gaps <a class="header-anchor" href="#open-questions-known-gaps" aria-label="Permalink to &quot;Open questions / known gaps&quot;">​</a></h2><ul><li><strong>Tab count 8 vs table total 21</strong> — the Figma draft disagrees with itself; both kept as drawn.</li><li><strong>Labels differ between View and Edit</strong> as drawn: &quot;Alt Title&quot; / &quot;Alternative Title&quot;, &quot;Topic &amp; Keywords&quot; / &quot;Topics and Keywords&quot;.</li><li><strong>Advisory descriptions</strong> exist in the design for the first advisory only. The other two expanded blank, so they carry placeholder copy written in the same voice (2026-09-28) — replace with designer/backend copy (the real text comes from the SEO check, <code>data-backend-todo=&quot;seo-advisory-detail&quot;</code> stays on empty descriptions).</li><li><strong>Narrow layout (designer-approved 2026-09-28, no Figma frames):</strong> container queries only. Tier 1 <code>@container cs-page (max-width: 1023px)</code> (the Seating Planner&#39;s stack point) stacks the columns — sidebar panels go below main in ONE full-width column (a two-up grid left holes beside short panels; masonry would make panels jump columns on expand — designer, 2026-09-28); the resize handle is hidden; in full width the main divider moves from its right edge to under it. Tier 2 lives in RecordSection: a self-container that stacks field rows label-over-value at ≤559 (192 label + ~45ch value + padding). The record header goes icon-only below 768 like every CC header (2026-09-30: Add plus, Edit pencil, Cancel x, Save check; labels in <code>.cc-header__btn-label</code>, names kept by <code>aria-label</code>; was labels-kept 2026-09-28). Verified 390 / 820 / 1024–1600: no page h-scroll; Steps table scrolls inside <code>datatables__body</code>.</li><li>The dark top navigation bar in the Figma screens is still the drawn frame (CC TopNavigation lives in the CC file); code uses the real shell.</li></ul><h2 id="narrow-frames-in-figma-2026-09-28" tabindex="-1">Narrow frames in Figma (2026-09-28) <a class="header-anchor" href="#narrow-frames-in-figma-2026-09-28" aria-label="Permalink to &quot;Narrow frames in Figma (2026-09-28)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Frame</th><th>Node</th><th>Shows</th></tr></thead><tbody><tr><td>Article View — Narrow (page ≤1023)</td><td><code>3905:142428</code></td><td>1024 wide: columns stacked, rows side by side</td></tr><tr><td>Article View — Mobile (390)</td><td><code>3905:143091</code></td><td>all stacked, FieldRow <code>Layout=Stacked</code>, actions rail hidden, header mobile dress</td></tr><tr><td>Article Edit — Narrow (page ≤1023)</td><td><code>3907:17461</code></td><td>as View</td></tr><tr><td>Article Edit — Mobile (390)</td><td><code>3907:17632</code></td><td>as View</td></tr><tr><td>Built from duplicates of the standard frames (kit instances kept). Mobile header: RecordHeader padding spacing/3 · spacing/4, title font/size-fixed/sm, buttons Size=sm; drawn top-nav breadcrumb clipped and user name hidden, as the code renders.</td><td></td><td></td></tr></tbody></table><h2 id="the-record-affino-com-article-626312-2026-09-29-code-first" tabindex="-1">The record: affino.com Article 626312 (2026-09-29, code-first) <a class="header-anchor" href="#the-record-affino-com-article-626312-2026-09-29-code-first" aria-label="Permalink to &quot;The record: affino.com Article 626312 (2026-09-29, code-first)&quot;">​</a></h2><p><strong><code>ArticleView.html</code> / <code>ArticleEdit.html</code> ARE affino.com Standard Item 626312</strong>, &quot;How charities can use Affino AI plugins&quot; (designer, 2026-09-29 — it replaced sf.affino.com 10007 because it is fully written). Read from <code>/control/standard-item-edit?Action=view&amp;StandardItemCode=626312</code> with a logged-in session, READ ONLY. Data + provenance: <code>record_article.py</code> (one table drives both screens). The Figma draft&#39;s six-section 9.0.11.25 content stays in <code>record_markup.py</code> for the component demos, and is still what Figma draws.</p><ul><li><strong>Main column:</strong> every live section in the live order — 15 sections, 79 fields (Presentation Style, Navigation, Introduction, Topics, SEO, Main Body, Geo Targeting, Comments And Ratings, Options, Advanced, Social, Article Questions, Summary, Security, Publication). Real copy throughout.</li><li><strong>Sidebar = the live side sections:</strong> Performance (56 impressions · 28 consumed · 0 bookmarked, top accounts Affino + Burning Nights CRPS Support), Recent Viewers (the 5 live viewers), Record (code 626312), Meta Information (Topics), Index Status (3), Audit. SEO Health stays demo (not on the live view).</li><li>Check-marks read from the live icons (TBY = yes, TBN = no): only <strong>Live</strong> is on. Embargo End&#39;s live <code>01/01/1900 00:00</code> is the platform&#39;s &quot;not set&quot; and renders unset.</li><li><strong>Known gaps:</strong> the thumbnail / main image is the repo placeholder (the real asset was not copied); the Performance chart series is still the demo series (its scale does not match 56 impressions); &quot;Impression Per Day&quot; 0.15 is derived (56 / 365). Viewer avatars are generated placeholders.</li><li><strong>New FieldRow kinds, code-first — FLAG FOR FIGMA:</strong> <code>rich</code>, <code>checkbox</code>, <code>date</code> / <code>datetime</code>, <code>lookup</code>, <code>image</code>, <code>file</code> (see FieldRow.figma-notes.md). FactPanel gained <code>.fact-panel__empty</code>.</li><li>Handover: <code>record-lookup</code>, <code>record-datetime</code>, <code>record-rich-text</code>, <code>record-media-file</code>.</li></ul><h2 id="selectors-2026-09-29" tabindex="-1">Selectors (2026-09-29) <a class="header-anchor" href="#selectors-2026-09-29" aria-label="Permalink to &quot;Selectors (2026-09-29)&quot;">​</a></h2><p>Section, Creator and Sort Order (lookup rows) and every MediaPicker <strong>Edit</strong> open the Selector pattern (<code>src/cc/patterns/Selector/</code>, code-first): Type=Single / Media / Sort. Multi Display, Topics, Countries and Authors keep the TagBox Multi Select Modal, which now has search and a count. Account is still an inert lookup (<code>record-lookup</code>).</p><h2 id="sidebar-chips-border-designer-2026-09-29" tabindex="-1">Sidebar chips border (designer, 2026-09-29) <a class="header-anchor" href="#sidebar-chips-border-designer-2026-09-29" aria-label="Permalink to &quot;Sidebar chips border (designer, 2026-09-29)&quot;">​</a></h2><p>Tertiary chips in the sidebar (FactPanel values, Recent Viewers companies) carry the subtle <code>--ai-border-secondary</code> line of the listing account chip. This is a Case B override in RecordScreen.css, scoped to <code>.record-screen__sidebar</code> and restated for hover and focus.</p><h2 id="figma-build-2026-09-30-—-colorpickerinput" tabindex="-1">Figma build 2026-09-30 — ColorPickerInput <a class="header-anchor" href="#figma-build-2026-09-30-—-colorpickerinput" aria-label="Permalink to &quot;Figma build 2026-09-30 — ColorPickerInput&quot;">​</a></h2><p><strong>ColorPickerInput <code>3929:19338</code></strong> (State Empty | Filled), View &amp; Edit kit &quot;Code-first components&quot;. Empty reads None.</p><h2 id="figma-build-2026-09-30-—-the-code-first-screens" tabindex="-1">Figma build 2026-09-30 — the code-first screens <a class="header-anchor" href="#figma-build-2026-09-30-—-the-code-first-screens" aria-label="Permalink to &quot;Figma build 2026-09-30 — the code-first screens&quot;">​</a></h2><p>View &amp; Edit page, right of the kit: <strong>Import step <code>3933:19459</code></strong>, <strong>Add content step <code>3933:149547</code></strong> (its 20-row main section is a detached RecordSection — the set has 8 row slots), <strong>Add dynamic form step <code>3933:150608</code></strong>, <strong>Add a step chooser <code>3933:147201</code></strong> and its <strong>Dynamic Form unavailable</strong> state <code>3933:147334</code> (the modal is composed from ModalHeader + the Modal Small look: its slot cannot be laid out from an instance). Still not in Figma: Selector (all types), RichTextEditor, PromptModifier.</p><p><strong>Card border + shadow (designer, 2026-10-02):</strong> RecordTabs, RecordSection and the sidebar FactPanels use <code>--ai-border-card</code> + <code>--ai-shadow-2xs</code> (RecordScreen.css), the same as the listing cards. In standard width only for tabs and sections, since full width keeps their flush rules. FactPanels keep <code>border/card</code> in full width but drop the shadow. Nested cards inside them are unchanged. The Steps table gets it from the listing rule (it sits in <code>.cc-listing</code>).</p><h2 id="contact-view-code-first-build-first-2026-10-07" tabindex="-1">Contact View (code-first &quot;build first&quot;, 2026-10-07) <a class="header-anchor" href="#contact-view-code-first-build-first-2026-10-07" aria-label="Permalink to &quot;Contact View (code-first &quot;build first&quot;, 2026-10-07)&quot;">​</a></h2><p><code>ContactView.html</code> (a fully filled contact) and <code>ContactViewSparse.html</code> (a sparse one), generated by <code>_generate.py</code> from <strong><code>record_contact.py</code></strong>: the kit&#39;s second record type. The structure is the live contact screen&#39;s (<code>/control/contacts?screen=UserView</code>, read 2026-10-07 from two real contacts); <strong>the people are invented</strong>: the live records hold personal details and these demos are public (Ofcom drama phone ranges, <code>.example</code> email domains). No Figma frame yet.</p><ul><li><strong>Header:</strong> Record type &quot;Contact&quot; + name; <strong>Edit</strong> (primary) + <strong>Add note</strong> (secondary), the live screen&#39;s other twelve quick actions / action links in the kebab (CC header rule), plus Go to list.</li><li><strong>Tabs:</strong> the live ten: Details, Demographic, Tasks, Communication, Commerce, Events, Analysis, Page analysis, Digital assets, Permissions; all built (see below). &quot;Badges&quot; and &quot;Assign customer signal&quot; sit beside the live tabs but are actions: Badges is in the kebab, Assign on the Customer signals panel. The list scrolls sideways when tight.</li><li><strong>Main:</strong> Contact (Photo = Avatar Size=4, Name, Job title, Email, Telephone, Mobile, Address) · Accounts (Account, Former accounts, Connections as chips) · Interests and lists (Topics, Mailing lists, Contact lists). Empty = &quot;-&quot;.</li><li><strong>Sidebar (CRM activity, designer 2026-10-07):</strong> Record facts · Customer signals (AvatarGroup, five then +N) · Latest activity · Open tasks · Contact notes · Opportunities (open / closed / won value + latest) · Events · Engagement. Panels link &quot;View all&quot; to the matching (unbuilt) tab.</li><li><strong>Kit additions</strong> (Article output byte-identical): <code>view_row(kind=&quot;html&quot;)</code>; <code>record_header(secondary=, more=)</code>; <code>record_tabs(tabs=)</code>; <code>record_list()</code> + <code>.record-list*</code> CSS (ViewerItem&#39;s type and spacing, the card border as divider); <code>build(crumbs=)</code>.</li><li><strong>Backend:</strong> <code>contact-record</code>, <code>-actions</code>, <code>-signals</code>, <code>-activity</code>, <code>-tasks</code>, <code>-notes</code>, <code>-opportunities</code>, <code>-crm-tabs</code>, <code>-sidebar</code> (HANDOVER.md, RecordScreen).</li><li>Checked: no overflow 340–1600px (page swept in 20px steps); kebab opens with the 13 actions.</li></ul><h3 id="contact-tabs-communication-and-commerce-2026-10-07" tabindex="-1">Contact tabs: Communication and Commerce (2026-10-07) <a class="header-anchor" href="#contact-tabs-communication-and-commerce-2026-10-07" aria-label="Permalink to &quot;Contact tabs: Communication and Commerce (2026-10-07)&quot;">​</a></h3><p><code>ContactViewCommunication.html</code> / <code>ContactViewCommerce.html</code> (+ the <code>Sparse</code> pair for the empty states): the tab bar, then full-width Datatables cards (as Article Steps), each a <code>data-fit=&quot;even&quot;</code> table (DatatablesFit.js). The sidebar panels&#39; &quot;View all&quot; now link here; the other tabs are still labels.</p><ul><li><strong>Communication</strong> = &quot;Contact notes 48&quot; + Add note: Note (title + summary, keep, ×3), Created (keep); drop order Updated by → Last updated → Opportunity → Account → By → Type. Footer &quot;Showing 8 of 48&quot; + Show more.</li><li><strong>Commerce</strong> = &quot;Open opportunities&quot; + Add opportunity, then &quot;Closed opportunities&quot;: Opportunity (keep, ×2), Stage (badge), Value (keep); drop order Next task → Notes → Owner → Contract → Close date → Last touch.</li><li>DatatablesFit fixes found here: when every column&#39;s content is wider than an even share, keep natural widths and share the rest by weight (unset widths had split the row equally, kebab included); the kebab always gets its own width; and once nothing more can drop, a fluid column wraps below its 192px floor before the row overflows. Re-swept Live Dashboard, Sales Leaderboard and Export System afterwards: no overflow at 340–1600px.</li></ul><h3 id="all-ten-contact-tabs-built-2026-10-07" tabindex="-1">All ten contact tabs built (2026-10-07) <a class="header-anchor" href="#all-ten-contact-tabs-built-2026-10-07" aria-label="Permalink to &quot;All ten contact tabs built (2026-10-07)&quot;">​</a></h3><p><code>ContactView{Tab}.html</code> and <code>ContactViewSparse{Tab}.html</code> for Demographic, Tasks, Communication, Commerce, Events, Analysis, PageAnalysis, DigitalAssets, Permissions (content read from the live tabs, <code>&amp;showTab=…</code>). Each tab page = the tab bar + full-width cards; related cards pair up in <code>.contact-tab-grid</code> (two ≥512px columns, one when narrow).</p><ul><li><strong>Demographic:</strong> a RecordSection per demographic set (named by the sites / areas it covers), values as chips.</li><li><strong>Tasks:</strong> Open tasks (+ Add task) and Closed tasks tables: Task (keep ×3), Due / Completed (keep), Assigned to, Priority (badge), Related to, Created.</li><li><strong>Events:</strong> Event attendance + Award entries tables, side by side.</li><li><strong>Analysis:</strong> Activity statistics (facts) + Engagement points by type; All customer signals + Latest activity; Views per day + Top views (empty states, as live).</li><li><strong>Page analysis:</strong> Profile page stats (three StatCards) with &quot;View on Site Analysis&quot;; Recent viewers + Referring URLs.</li><li><strong>Digital assets:</strong> Subscriptions (+ Subscription history / Edition circulation / Service credits links); Digital assets + Service credit entries.</li><li><strong>Permissions:</strong> User preferences + Terms and conditions; User permissions; the four subscription / download histories.</li><li><strong>Card head:</strong> title + <strong>count chip</strong> (house rule: a count sits in a neutral chip, never in running text; the sidebar&#39;s Contact notes / Customer signals counts moved into chips too, via <code>fact_panel(count=)</code> + <code>count_chip()</code>), min-height = the Add button&#39;s 32px so heads match with or without a button; the Add button goes icon-only below 767 (cs-page) so it never wraps under the title.</li><li><strong>Fix:</strong> the sidebar&#39;s saved panel order was keyed <code>:article</code> for every record type, so Contact&#39;s order rearranged Article&#39;s; it is now keyed per <code>data-record-type</code> (<code>page(record_type=)</code>).</li><li>Checked: all 20 contact pages at 390 / 1024 / 1600px in iframes: no overflow, matching head heights side by side.</li></ul><h3 id="analysis-made-visual-equal-panel-heights-2026-10-07-designer" tabindex="-1">Analysis made visual + equal panel heights (2026-10-07, designer) <a class="header-anchor" href="#analysis-made-visual-equal-panel-heights-2026-10-07-designer" aria-label="Permalink to &quot;Analysis made visual + equal panel heights (2026-10-07, designer)&quot;">​</a></h3><ul><li><strong>Equal heights:</strong> cards in a <code>.contact-tab-grid</code> row stretch to the tallest (<code>align-items: stretch</code>), on every tab.</li><li><strong>Analysis:</strong> four StatCard tiles (Logins 365 days, Page views 365 days, Message opens, Forum posts; lagoon-first accents) · <strong>Engagement points by type</strong> as a sorted horizontal bar chart · <strong>Activity by month</strong> (customer-signal events, 12 months, the current month soft + edged &quot;to date&quot;) · <strong>All customer signals</strong> as a ranked list: each signal&#39;s icon, name, count and a share-of-top bar (Live Dashboard&#39;s leaderboard) · <strong>Latest activity</strong> with each event&#39;s signal icon · the remaining statistics as facts · Content views (empty state, as live).</li><li>Charts: <code>ContactCharts.js</code> draws any <code>canvas[data-contact-chart]</code> (one lagoon series, house bar shape, tooltip, no legend; values in a &quot;View as table&quot; under each). Dataviz rules: single hue, sorted bars, no dual axis.</li><li><strong>Signal icons in timelines:</strong> <code>record_list</code> takes an optional glyph per row; the sidebar&#39;s Latest activity uses it too.</li><li>Checked all 20 contact pages at 390 / 1024 / 1600: no overflow; side-by-side cards and heads match; all 12 charts draw.</li><li><strong>Trail layout (2026-10-07, designer, Flowbite Timeline):</strong> Latest activity (sidebar + Analysis) is <code>record_list(timeline=True)</code>: a 1px border-secondary line runs behind the 32px signal-icon circles (centred, first to last; the house VersionHistory timeline pattern), the time sits above the event in contrast ink, no row dividers; each circle has a surface-primary ring so the line reads as a trail between events. Measured: icon centres and the line share one x.</li><li><strong>Permissions reworked (2026-10-07, designer picked ideas 1, 2, 4):</strong> yes / no preferences as read-only switches (Toggle xxs, <code>aria-disabled</code> so Toggle.js leaves them, not greyed) with On / Off in words; Terms and conditions sorted newest first, the latest badged <strong>Current</strong> and older versions muted; the four subscription / download histories merged into one <strong>Subscription and download history</strong> trail (timeline layout, newest first, an icon per kind: mailing list, content subscription, media download, forum subscription).</li><li><strong>Signal icon colours (demo only, 2026-10-07, designer):</strong> the glyph circles standing in for customer-signal badge images take the StatCard soft scheme (<code>accent-*-soft</code> background, <code>accent-*-soft-fg</code> glyph), one fixed hue per glyph (<code>record_markup.signal_hue</code>, lagoon first, blue last, no red) so a signal is the same colour everywhere: the sidebar AvatarGroup, the Analysis ranked list, the activity and history trails, and Article View&#39;s Recent Viewers signals. Live builds replace the circles with each signal&#39;s Badge On image.</li><li><strong>Rings follow the surface (2026-10-07):</strong> the AvatarGroup ring and the timeline icon ring read <code>--ring-surface</code>, set by AvatarGroup.js from the surface they sit on (the timeline list carries <code>data-ring-surface</code>).</li></ul><h2 id="order-view-code-first-build-first-2026-10-07-—-not-in-figma-yet" tabindex="-1">Order View (code-first &quot;build first&quot;, 2026-10-07) — NOT in Figma yet <a class="header-anchor" href="#order-view-code-first-build-first-2026-10-07-—-not-in-figma-yet" aria-label="Permalink to &quot;Order View (code-first &quot;build first&quot;, 2026-10-07) — NOT in Figma yet&quot;">​</a></h2><p><code>OrderView.html</code>, generated from <code>record_order.py</code> (content) + <code>OrderView.js</code> (processing flows). Structure from the live <code>/control/order-processing?OrderCode=100412</code>; the order, product and dates are the live order&#39;s, the <strong>customer is invented</strong> (Thomas Reid, Harbour Lane Publishing; Ofcom drama phone range, <code>.example</code> email, documentation IP range).</p><ul><li><strong>Header:</strong> Edit (primary) + Update status (secondary); the live receipt / invoice / label / despatch links in the kebab, then Go to list (the Orders listing).</li><li><strong>Main column:</strong> Order · Line items card (DatatablesFit table, attendee block &quot;0 of 1 assigned&quot; + Add attendees, right-aligned totals) · Payment · Payment details card · Customer (+ end user) · Addresses (invoice / billing / delivery) · Delivery (AWB, Invoices sent) · Additional information.</li><li><strong>Sidebar:</strong> Status (badge + Change, order facts) · Status history (trail timeline) · Customer · Contact notes · Next task · Audit.</li><li><strong>Processing modals (working demo, in memory):</strong> Update status (all 16 listing statuses, note, notify) · Send receipt · Send receipt with invoice · Send message with invoice · Despatch notification (courier + AWB → Shipped) · Add attendee (&quot;Use the customer&#39;s details&quot; prefill). Each validates required / email fields inline, closes, updates the page, appends history, toasts.</li><li>Status badge tones: done = success, waiting = warning, moving = info, stopped = neutral (<code>STATUS_TONE</code> in both the .py and the .js).</li><li>Backend rows: <code>order-*</code> in HANDOVER.md.</li></ul><h2 id="figma" tabindex="-1">Figma <a class="header-anchor" href="#figma" aria-label="Permalink to &quot;Figma&quot;">​</a></h2><p><a href="https://www.figma.com/design/Lus07xi8pPXLN87sQIyrEt/Affino---Design-System?node-id=3842-147640" target="_blank" rel="noreferrer">Open in Figma</a></p>',41))])}const k=d(h,[["render",g]]);export{v as __pageData,k as default};
